<script setup>import { orders } from '../../api/mock'; import AppIcon from '../../components/AppIcon.vue'; const status={PAID:'已完成',REFUNDED:'已退款',PARTIAL_REFUND:'部分退款'},pay={WECHAT:'微信支付',ALIPAY:'支付宝',BANK_CARD:'银行卡',CASH:'现金',MIXED:'组合支付'}</script>
<template><div class="resource-page"><section class="resource-card"><header class="resource-tools"><div><h2>交易订单</h2><p>查询门店订单、支付流水、退款与反结账记录</p></div><button class="secondary">导出明细</button></header><div class="table-filters"><div class="filter-search"><AppIcon name="search"/><input placeholder="订单号 / 会员 / 收银员"/></div><button>今日 00:00—现在<AppIcon name="arrow" :size="13"/></button><button>全部门店<AppIcon name="arrow" :size="13"/></button><button>全部状态<AppIcon name="arrow" :size="13"/></button><span>共 1,147 笔</span></div><table class="data-table"><thead><tr><th>订单号 / 时间</th><th>门店 / 收银机</th><th>会员</th><th>商品数</th><th>应收</th><th>优惠</th><th>实收</th><th>支付方式</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in orders" :key="o.orderNo"><td><b>{{o.orderNo}}</b><small>{{o.createdAt}}</small></td><td><b>{{o.storeName}}</b><small>{{o.registerNo}} · {{o.cashierName}}</small></td><td>{{o.memberName||'散客'}}</td><td>{{o.itemCount}} 件</td><td>¥{{o.subtotal.toFixed(2)}}</td><td class="discount">−¥{{o.discount.toFixed(2)}}</td><td><strong>¥{{o.payable.toFixed(2)}}</strong></td><td>{{pay[o.paymentMethod]}}</td><td><em class="status-pill" :class="o.status.toLowerCase()">{{status[o.status]}}</em></td><td><button class="text-action">详情</button></td></tr></tbody></table></section></div></template>
